use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() < 0x1_0000_0000, // Ensure the length of the vector is within reasonable bounds
        ensures
            result.len() == a.len(), // The output vector has the same length as the input
            forall(|i: nat| i < a.len() ==> result[i] == a[i]), // Each element in the output matches the input
    {
        let mut result: Vec<T> = Vec::new(); // Initialize an empty vector for the result
        let mut i: nat = 0; // Initialize an index variable

        while i < a.len() // Loop until we have copied all elements
            invariant
                i <= a.len(), // The index is within bounds of the input vector
                result.len() == i, // The length of the result vector is equal to the index
                forall(|j: nat| j < i ==> result[j] == a[j]), // All previously copied elements match
            decreases a.len() - i, // Decrease clause to ensure termination
        {
            result.push(a[i]); // Copy the element from input to output
            i = i + 1; // Increment the index
        }

        result // Return the copied vector
    }
}

